#include <list>
#include <iostream>

int main() {
    std::list<int> l1 = {1, 2, 3};
    std::list<int> l2 = {4, 5, 6};

    // Splice all of l2 into l1 before element '2'
    auto pos = ++l1.begin(); // points to 2
    l1.splice(pos, l2);

    // l1 is now {1, 4, 5, 6, 2, 3}
    // l2 is now {}

    std::cout << "L1 size: " << l1.size() << ", L2 size: " << l2.size() << "\n";

    // Example of moving one element within the same list (safe)
    auto it_six = l1.begin();
    std::advance(it_six, 3); // points to 6
    l1.splice(l1.end(), l1, it_six);
    // l1 is now {1, 4, 5, 2, 3, 6}
}
